package com.game_manager.gm.report;
import static org.assertj.core.api.Assertions.assertThat; import java.io.*; import java.math.BigDecimal; import java.sql.Timestamp; import java.time.Instant; import java.util.UUID; import javax.sql.DataSource; import org.apache.poi.xssf.usermodel.XSSFWorkbook; import org.junit.jupiter.api.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.jdbc.datasource.embedded.*;
class ReportGeneratorTest {DataSource source;JdbcTemplate db;ReportGenerator generator;@BeforeEach void setup(){source=new EmbeddedDatabaseBuilder().setType(EmbeddedDatabaseType.H2).build();db=new JdbcTemplate(source);db.execute("CREATE TABLE orders(id VARCHAR(36),customer_id VARCHAR(36),created_at TIMESTAMP,status VARCHAR(20),total_price DECIMAL(12,2))");generator=new ReportGenerator(db);}@AfterEach void close(){((EmbeddedDatabase)source).shutdown();}
 @Test void rendersGoldenCsvXlsxPdfAndNeutralizesFormula()throws Exception{UUID owner=UUID.randomUUID();db.update("INSERT INTO orders VALUES(?,?,?,?,?)",UUID.randomUUID().toString(),owner.toString(),Timestamp.from(Instant.parse("2026-01-02T10:00:00Z")),"COMPLETED",new BigDecimal("42.50"));for(ReportFormat format:ReportFormat.values()){ReportRequest request=request(format);ReportGenerator.Generated output=generator.generate(request,owner);assertThat(output.rows()).isEqualTo(1);assertThat(output.bytes()).isNotEmpty();if(format==ReportFormat.CSV)assertThat(new String(output.bytes(),java.nio.charset.StandardCharsets.UTF_8)).contains("COMPLETED","42.50");if(format==ReportFormat.XLSX)try(XSSFWorkbook workbook=new XSSFWorkbook(new ByteArrayInputStream(output.bytes()))){assertThat(workbook.getSheetAt(0).getRow(1).getCell(2).getStringCellValue()).isEqualTo("COMPLETED");}if(format==ReportFormat.PDF)assertThat(output.bytes()).startsWith("%PDF".getBytes());}assertThat(ReportGenerator.safe("=HYPERLINK(\"bad\")")).startsWith("'");}
 private ReportRequest request(ReportFormat format){ReportRequest request=new ReportRequest();request.setDefinitionKey("orders");request.setFormat(format);request.setFiltersJson("2026-01-01T00:00:00Z|2026-02-01T00:00:00Z");return request;}}
